using System.ComponentModel.DataAnnotations;
using System.Security.Claims;
using System.Text;
using EduSphere.Domain.Entities;
using EduSphere.Domain.Enums;
using EduSphere.Infrastructure;
using EduSphere.Web.Authorization;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;

namespace EduSphere.Web.Pages.People;

[Authorize(Policy = AuthorizationPolicies.UserManager)]
public sealed class StaffAdministrationModel(TenantDbContext db) : PageModel
{
    public IReadOnlyList<ApplicationUser> ParentUsers { get; private set; }=[]; public IReadOnlyList<StudentProfile> Students { get; private set; }=[];
    public IReadOnlyList<StaffProfile> Staff { get; private set; }=[]; public IReadOnlyList<TeacherProfile> Teachers { get; private set; }=[]; public IReadOnlyList<Branch> Branches { get; private set; }=[]; public IReadOnlyList<Department> Departments { get; private set; }=[];
    public IReadOnlyList<TeacherQualificationRecord> Qualifications { get; private set; }=[]; public IReadOnlyList<TeacherExperienceRecord> Experiences { get; private set; }=[]; public IReadOnlyList<StaffAttendanceRecord> Attendance { get; private set; }=[]; public IReadOnlyList<StaffLeaveRequest> Leaves { get; private set; }=[]; public IReadOnlyList<PayrollRun> PayrollRuns { get; private set; }=[];
    [TempData] public string? Feedback { get;set; }
    [BindProperty] public ParentLinkInput ParentLink {get;set;}=new(); [BindProperty] public StaffInput StaffForm {get;set;}=new(); [BindProperty] public QualificationInput Qualification {get;set;}=new(); [BindProperty] public ExperienceInput Experience {get;set;}=new(); [BindProperty] public AttendanceInput AttendanceForm {get;set;}=new(); [BindProperty] public LeaveInput Leave {get;set;}=new(); [BindProperty] public PayrollInput Payroll {get;set;}=new();
    public sealed class ParentLinkInput { [Required] public Guid? ParentUserId {get;set;} [Required] public Guid? StudentProfileId {get;set;} public GuardianRelationship Relationship {get;set;}=GuardianRelationship.Guardian; public bool IsPrimary {get;set;} public bool CanPickup {get;set;}=true; }
    public sealed class StaffInput { [Required] public Guid? UserId {get;set;} [Required] public Guid? BranchId {get;set;} public Guid? DepartmentId {get;set;} [Required] public string EmployeeNumber {get;set;}=""; [Required] public string FirstName {get;set;}=""; [Required] public string LastName {get;set;}=""; public string? Designation {get;set;} public EmploymentType EmploymentType {get;set;} public DateOnly JoiningDate {get;set;}=DateOnly.FromDateTime(DateTime.Today); public decimal BasicSalary {get;set;} }
    public sealed class QualificationInput { [Required] public Guid? TeacherProfileId {get;set;} [Required] public string Qualification {get;set;}=""; public string? Institution {get;set;} public string? Specialization {get;set;} public int? CompletionYear {get;set;} public bool IsVerified {get;set;} }
    public sealed class ExperienceInput { [Required] public Guid? TeacherProfileId {get;set;} [Required] public string Organization {get;set;}=""; [Required] public string Designation {get;set;}=""; public DateOnly FromDate {get;set;}=DateOnly.FromDateTime(DateTime.Today.AddYears(-1)); public DateOnly? ToDate {get;set;} public bool IsCurrent {get;set;} }
    public sealed class AttendanceInput { [Required] public Guid? StaffProfileId {get;set;} public DateOnly Date {get;set;}=DateOnly.FromDateTime(DateTime.Today); public StaffAttendanceStatus Status {get;set;} public TimeOnly? CheckIn {get;set;} public TimeOnly? CheckOut {get;set;} }
    public sealed class LeaveInput { [Required] public Guid? StaffProfileId {get;set;} [Required] public string LeaveType {get;set;}="Annual"; public DateOnly FromDate {get;set;}=DateOnly.FromDateTime(DateTime.Today); public DateOnly ToDate {get;set;}=DateOnly.FromDateTime(DateTime.Today); [Required] public string Reason {get;set;}=""; }
    public sealed class PayrollInput { [Required] public Guid? BranchId {get;set;} [Range(2000,2200)] public int Year {get;set;}=DateTime.Today.Year; [Range(1,12)] public int Month {get;set;}=DateTime.Today.Month; }
    public async Task OnGetAsync()=>await LoadAsync();
    public async Task<IActionResult> OnPostLinkParentAsync()=>await SaveAsync(nameof(ParentLink),async()=>{var parent=await db.Users.SingleAsync(x=>x.Id==ParentLink.ParentUserId);var student=await db.StudentProfiles.SingleAsync(x=>x.Id==ParentLink.StudentProfileId);if(await db.StudentGuardians.AnyAsync(x=>x.ParentUserId==parent.Id&&x.StudentProfileId==student.Id))throw new InvalidOperationException("This parent is already linked to the student.");db.StudentGuardians.Add(new StudentGuardian{StudentProfileId=student.Id,ParentUserId=parent.Id,FullName=parent.FullName,Email=parent.Email,PhoneNumber=parent.PhoneNumber,Relationship=ParentLink.Relationship,IsPrimary=ParentLink.IsPrimary,CanPickup=ParentLink.CanPickup,HasPortalAccess=true});if(!await db.UserBranchAssignments.AnyAsync(x=>x.UserId==parent.Id&&x.BranchId==student.BranchId))db.UserBranchAssignments.Add(new UserBranchAssignment{UserId=parent.Id,BranchId=student.BranchId,IsPrimary=false});await db.SaveChangesAsync();});
    public async Task<IActionResult> OnPostSaveStaffAsync()=>await SaveAsync(nameof(StaffForm),async()=>{var user=await db.Users.SingleAsync(x=>x.Id==StaffForm.UserId);var profile=await db.StaffProfiles.SingleOrDefaultAsync(x=>x.UserId==user.Id);if(profile is null){profile=new StaffProfile{UserId=user.Id};db.StaffProfiles.Add(profile);}profile.BranchId=StaffForm.BranchId;profile.DepartmentId=StaffForm.DepartmentId;profile.EmployeeNumber=StaffForm.EmployeeNumber;profile.FirstName=StaffForm.FirstName;profile.LastName=StaffForm.LastName;profile.Email=user.Email;profile.Designation=StaffForm.Designation;profile.EmploymentType=StaffForm.EmploymentType;profile.JoiningDate=StaffForm.JoiningDate;var pay=await db.StaffPayrollProfiles.SingleOrDefaultAsync(x=>x.StaffProfileId==profile.Id);if(pay is null){pay=new StaffPayrollProfile{StaffProfile=profile};db.StaffPayrollProfiles.Add(pay);}pay.BasicSalary=StaffForm.BasicSalary;await db.SaveChangesAsync();});
    public async Task<IActionResult> OnPostQualificationAsync()=>await SaveAsync(nameof(Qualification),async()=>{db.TeacherQualificationRecords.Add(new(){TeacherProfileId=Qualification.TeacherProfileId!.Value,Qualification=Qualification.Qualification,Institution=Qualification.Institution,Specialization=Qualification.Specialization,CompletionYear=Qualification.CompletionYear,IsVerified=Qualification.IsVerified});await db.SaveChangesAsync();});
    public async Task<IActionResult> OnPostExperienceAsync()=>await SaveAsync(nameof(Experience),async()=>{if(Experience.ToDate<Experience.FromDate)throw new InvalidOperationException("Experience end date must follow its start date.");db.TeacherExperienceRecords.Add(new(){TeacherProfileId=Experience.TeacherProfileId!.Value,Organization=Experience.Organization,Designation=Experience.Designation,FromDate=Experience.FromDate,ToDate=Experience.ToDate,IsCurrent=Experience.IsCurrent});await db.SaveChangesAsync();});
    public async Task<IActionResult> OnPostAttendanceAsync()=>await SaveAsync(nameof(AttendanceForm),async()=>{var staff=await db.StaffProfiles.SingleAsync(x=>x.Id==AttendanceForm.StaffProfileId);var item=await db.StaffAttendanceRecords.SingleOrDefaultAsync(x=>x.StaffProfileId==staff.Id&&x.AttendanceDate==AttendanceForm.Date);if(item is null){item=new(){StaffProfileId=staff.Id,BranchId=staff.BranchId!.Value,AttendanceDate=AttendanceForm.Date};db.Add(item);}item.Status=AttendanceForm.Status;item.CheckIn=AttendanceForm.CheckIn;item.CheckOut=AttendanceForm.CheckOut;await db.SaveChangesAsync();});
    public async Task<IActionResult> OnPostLeaveAsync()=>await SaveAsync(nameof(Leave),async()=>{if(Leave.ToDate<Leave.FromDate)throw new InvalidOperationException("Leave end date must follow its start date.");var staff=await db.StaffProfiles.SingleAsync(x=>x.Id==Leave.StaffProfileId);db.StaffLeaveRequests.Add(new(){StaffProfileId=staff.Id,BranchId=staff.BranchId!.Value,LeaveType=Leave.LeaveType,FromDate=Leave.FromDate,ToDate=Leave.ToDate,Reason=Leave.Reason,Status=StaffLeaveStatus.Submitted});await db.SaveChangesAsync();});
    public async Task<IActionResult> OnPostReviewLeaveAsync(Guid id,StaffLeaveStatus status){var item=await db.StaffLeaveRequests.SingleAsync(x=>x.Id==id);item.Status=status;item.ReviewedOn=DateTime.UtcNow;item.ReviewedByUserId=Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);await db.SaveChangesAsync();return RedirectToPage();}
    public async Task<IActionResult> OnPostPayrollAsync()=>await SaveAsync(nameof(Payroll),async()=>{if(await db.PayrollRuns.AnyAsync(x=>x.BranchId==Payroll.BranchId&&x.Year==Payroll.Year&&x.Month==Payroll.Month))throw new InvalidOperationException("A payroll run already exists for this branch and month.");var profiles=await db.StaffPayrollProfiles.Include(x=>x.StaffProfile).Where(x=>x.IsActive&&x.StaffProfile!.BranchId==Payroll.BranchId).ToListAsync();var run=new PayrollRun{BranchId=Payroll.BranchId!.Value,Year=Payroll.Year,Month=Payroll.Month,Status=PayrollRunStatus.Calculated};run.Entries=profiles.Select(x=>new PayrollEntry{StaffProfileId=x.StaffProfileId,BasicSalary=x.BasicSalary,Allowances=x.Allowances,Deductions=x.Deductions,NetPay=x.BasicSalary+x.Allowances-x.Deductions}).ToList();db.Add(run);await db.SaveChangesAsync();});
    public async Task<FileContentResult> OnGetPayrollExportAsync(Guid id){var run=await db.PayrollRuns.Include(x=>x.Entries).ThenInclude(x=>x.StaffProfile).SingleAsync(x=>x.Id==id);var csv=new StringBuilder("EmployeeNumber,Name,Basic,Allowances,Deductions,NetPay\r\n");foreach(var x in run.Entries)csv.AppendLine($"{x.StaffProfile?.EmployeeNumber},\"{x.StaffProfile?.FirstName} {x.StaffProfile?.LastName}\",{x.BasicSalary},{x.Allowances},{x.Deductions},{x.NetPay}");run.Status=PayrollRunStatus.Exported;run.ExportFileName=$"payroll-{run.Year}-{run.Month:00}.csv";await db.SaveChangesAsync();return File(Encoding.UTF8.GetBytes(csv.ToString()),"text/csv",run.ExportFileName);}
    private async Task<IActionResult> SaveAsync(string prefix,Func<Task> save){foreach(var key in ModelState.Keys.Where(x=>!x.StartsWith(prefix+".")).ToList())ModelState.Remove(key);if(!ModelState.IsValid){await LoadAsync();return Page();}try{await save();Feedback="Record saved.";return RedirectToPage();}catch(Exception ex)when(ex is InvalidOperationException or DbUpdateException){ModelState.AddModelError("",ex is DbUpdateException?"The record conflicts with existing data.":ex.Message);await LoadAsync();return Page();}}
    private async Task LoadAsync(){ParentUsers=await db.Users.Where(x=>x.UserType==UserType.Parent).OrderBy(x=>x.FirstName).ToListAsync();Students=await db.StudentProfiles.OrderBy(x=>x.FirstName).ToListAsync();Staff=await db.StaffProfiles.Include(x=>x.User).OrderBy(x=>x.FirstName).ToListAsync();Teachers=await db.TeacherProfiles.OrderBy(x=>x.FirstName).ToListAsync();Branches=await db.Branches.OrderBy(x=>x.Name).ToListAsync();Departments=await db.Departments.OrderBy(x=>x.Name).ToListAsync();Qualifications=await db.TeacherQualificationRecords.OrderByDescending(x=>x.CompletionYear).ToListAsync();Experiences=await db.TeacherExperienceRecords.OrderByDescending(x=>x.FromDate).ToListAsync();Attendance=await db.StaffAttendanceRecords.OrderByDescending(x=>x.AttendanceDate).Take(100).ToListAsync();Leaves=await db.StaffLeaveRequests.Include(x=>x.StaffProfile).OrderByDescending(x=>x.FromDate).Take(100).ToListAsync();PayrollRuns=await db.PayrollRuns.OrderByDescending(x=>x.Year).ThenByDescending(x=>x.Month).ToListAsync();}
}
